// === Tab: mySketch ===
var mass = [];//小球质量，即小球的大小
var positionX = [];//小球x坐标
var positionY = [];//小球y坐标
var velocityX = [];//小球x方向的速度
var velocityY = [];//小球y方向的速度

/////////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {//初始化函数，只运行一次
	createCanvas(windowWidth, windowHeight);//构建同窗口大小相同的画布
	noStroke();//设置为无边框
	fill(64, 255, 255, 192);//设置填充颜色与透明度


}

/////////////////////////////////////////////////////////////////////////////////////////////////////

function draw() {//该函数每帧执行一次，每次执行都会更改所有粒子的位置信息，然后在相应位置绘制圆形

	background(34);//设置背景颜色，同时覆盖上一帧的内容
	//background(34,23,56);

	//循环遍历所有数组，根据所有小球的位置，修改所有小球的速度
	for (var particleA = 0; particleA < mass.length; particleA++) {

		var accelerationX = 0, accelerationY = 0;

		for (var particleB = 0; particleB < mass.length; particleB++) {

			if (particleA != particleB) {
				var distanceX = positionX[particleB] - positionX[particleA];
				var distanceY = positionY[particleB] - positionY[particleA];
				var distance = sqrt(distanceX * distanceX + distanceY * distanceY);

				if (distance < 1) distance = 1;

				var force = (distance - 320) * mass[particleB] / distance;
				accelerationX += force * distanceX;
				accelerationY += force * distanceY;
			}
		}

		velocityX[particleA] = velocityX[particleA] * 0.99 + accelerationX * mass[particleA];
		velocityY[particleA] = velocityY[particleA] * 0.99 + accelerationY * mass[particleA];

	}

	//根据数组中的位置与速度信息，更新位置并画出所有小球
	for (var particle = 0; particle < mass.length; particle++) {

		positionX[particle] += velocityX[particle];//使小球向速度的方向移动
		positionY[particle] += velocityY[particle];//使小球向速度的方向移动

		//画出圆形：positionX与positionY为圆心坐标，以质量控制圆的宽和高
		ellipse(positionX[particle], positionY[particle], mass[particle] * 1000, mass[particle] * 1000);
	}
}

/////////////////////////////////////////////////////////////////////////////////////////////////////
//自定义函数，添加小球信息,当鼠标事件发生时调用该函数
function addNewParticle() {

	mass.push(random(0.003, 0.03));//质量随机
	positionX.push((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));//以鼠标位置作为小球的初始位置
	positionY.push((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));//以鼠标位置作为小球的初始位置

	velocityX.push(0);//初始速度为0
	velocityY.push(0);//初始速度为0
}

/////////////////////////////////////////////////////////////////////////////////////////////////////
//当鼠标点击时，调用该函数
function mouseClicked() {
	addNewParticle();//添加小球信息
}

/////////////////////////////////////////////////////////////////////////////////////////////////////
//当鼠标拖动时，调用该函数
function mouseDragged() {
	addNewParticle();//添加小球信息
}

